@bot.on_message() # پولینگ - polling
async def handler_polling(msg: Message):
    await msg.reply("پاسخ خودکار")
    if msg.text == "/off":
        bot.stop()

@bot.on_message_updates() # وبهوک - webhook
async def handler_webhook(msg: Message):
    await msg.reply("پاسخ خودکار")
    if msg.text == "/off":
        bot.stop()

# سایر دکوراتورها:
# @bot.on_edit() , @bot.on_delete() , @bot.on_all_message()
# @bot.on_edit_updates() , @bot.on_delete_updates() , @bot.on_all_message_updates()

msg = await bot.get_message("b...", "msg_id")
if msg:
    print(msg.text)

msgs = await bot.get_messages("b...", "msg_id", get_befor=5)
for m in msgs:
